  // Teach-me add-on: turn the topic's sample data into an infographic brief

  function originalInfographicAsk(key) {
    let s = '';
    const sm = (typeof SAMPLES !== 'undefined') ? SAMPLES[key] : null;
    if (sm) {
      const raw = (sm.csv || sm.raw || '').split('\n').map(l => l.replace(/(^|,)!/g, '$1')).slice(0, 12).join('\n');
      s += '\n\nHere is the sample data from this topic:\n' + raw;
    }
    s += '\n\nThen visualize it as an infographic. Give me (1) the chart type you would use for the sample and why, and (2) a ready-to-paste image-generation prompt for a clean, light-coloured infographic titled "' + topic0(key) + ': optimizing the data" with: a bold title; a split layout with a red "Common mistake" panel on the left and a blue "Best practice" panel on the right, each showing a small chart or table drawn from the sample; a one-line rule or formula box in the middle; and a row of "Three fixes" with numbered icons. Describe every element, its labels and its colours so an AI image tool can render it directly.';
    return s;
  }

  function infographicAsk(key){
    const meta=APPROVED_GRAPHIC_META[key];if(!meta||meta.status!=='update')return '';
    const sample=typeof SAMPLES!=='undefined'?SAMPLES[key]:null;const raw=sample?(sample.csv||sample.raw||'').split('\n').map(l=>l.replace(/(^|,)!/g,'$1')).slice(0,12).join('\n'):'';
    const spec='Create a precise professional infographic titled "'+topic0(key)+'". Use a pure white canvas and white cards, midnight-navy typography, and restrained teal, blue, purple, coral and orange line/text accents. Use the approved structure: clear topic heading and short explanation; two bordered panels (Common Mistake and Best Practice); a compact topic-appropriate rule, formula or decision criterion; three equal numbered action cards. Tailor the diagram to this exact lesson: use the actual chart, workflow, code structure, table or evidence relationship it needs. Never copy OSINT sources, dates, reliability weights or a circular source loop into an unrelated lesson. Keep original definitions, units, dates and sample values. Preserve meaningful chart axes and denominators. Use readable type, thin crisp geometry and no shadows or colored panel fills. Clearly label synthetic examples. A rule of thumb is not a mathematical law or validated probability. Include full labels and concrete fixes. Provide the chart choice and a complete image-generation prompt.';
    return (raw?'\n\nTopic sample data:\n'+raw:'')+'\n\n'+spec;
  }
  function topic0(key) { const p = PROMPTS[key]; return p ? p[0] : key; }

  const PROMPT_ICONS = { teach:'🎓', apply:'🛠️', review:'🔎' };
  function buildPrompts(key) {
    const p = PROMPTS[key];
    if (!p) return null;
    const topic = p[0], apply = p[1];
    return [
      { id:'teach', icon:PROMPT_ICONS.teach, label:'Teach me',
        hint:'Plain-English explanation with an example',
        text:'Act as a patient data analytics tutor. Explain "' + topic + '" to a business professional with no statistics background. Use one everyday business example, show any formula or syntax, and finish with 3 common mistakes and how to avoid them.' + infographicAsk(key) },
      { id:'apply', icon:PROMPT_ICONS.apply, label:'Apply to my work',
        hint:'Replace [brackets] with your details',
        text:apply },
      { id:'review', icon:PROMPT_ICONS.review, label:'Check my work',
        hint:'Paste your own analysis to be reviewed',
        text:'Review my work on "' + topic + '". Here is what I did and concluded: [paste your steps, numbers and conclusion]. Check for mistakes in method, assumptions, interpretation and wording. Give me a corrected version and a short list of what to improve.' }
    ];
  }

