  const modalEl = overlay.querySelector('.modal');
  const modalHead = document.getElementById('modalHead');
  const modalIcon = document.getElementById('modalIcon');
  const modalTag = document.getElementById('modalTag');
  const modalTitle = document.getElementById('modalTitle');
  const modalBody = document.getElementById('modalBody');
  const modalClose = document.getElementById('modalClose');
  const modalFoot = document.getElementById('modalFoot');

  // ---- progress ("learned") stored per browser; wrapped because storage can be blocked
  const LS_KEY = 'ai-data-analytics-hub-learned-v1';
  let learned = {};
  try { learned = JSON.parse(localStorage.getItem(LS_KEY) || '{}') || {}; } catch (e) { learned = {}; }
  function saveLearned() { try { localStorage.setItem(LS_KEY, JSON.stringify(learned)); } catch (e) {} }

  const allTiles = Array.from(document.querySelectorAll('.cheat-tile'));
  const tileOrder = allTiles.map(t => t.dataset.modal);
  function panelOf(tile) { return tile.closest('.tab-panel'); }
  function groupLabel(tile) {
    const h = tile.closest('.cheat-group')?.querySelector('.cheat-group-head h3');
    return h ? h.textContent.trim() : '';
  }
  function tileFor(key) { return allTiles.find(t => t.dataset.modal === key); }


  // ---- roadmap view: lay a module's sections out as a branching roadmap
  function buildRoadmap(panelId) {
    const panel = document.getElementById(panelId);
    if (!panel || panel.querySelector('.rm')) return;
    const groups = Array.from(panel.querySelectorAll('.cheat-group'));
    if (!groups.length) return;
    const pal = [['#475569'], ['#2563eb'], ['#7c3aed'], ['#0d9488'], ['#ea580c'], ['#be123c'], ['#4d7c0f'], ['#4338ca']];
    const rm = document.createElement('div');
    rm.className = 'rm';
    let html = '<div class="rm-legend" style="--rmc:#2563eb"><span><i class="core"></i>Section starting point</span>'
      + '<span><i></i>Topic</span><span><i class="done"></i>Marked as learned</span>'
      + '<span>Click any node to open it</span></div><div class="rm-track">';
    groups.forEach((g, gi) => {
      const name = (g.querySelector('.cheat-group-head h3') || {}).textContent || '';
      const tiles = Array.from(g.querySelectorAll('.cheat-tile'));
      const c = pal[gi % pal.length][0];
      html += '<div class="rm-stage" style="--rmc:' + c + '">';
      html += '<div class="rm-head"><span><b>' + (gi + 1) + '</b>' + escH(name) + '</span></div>';
      tiles.forEach((t, ti) => {
        const side = ti % 2 === 0 ? 'l' : 'r';
        const title = (t.querySelector('.ct-title') || {}).textContent || '';
        const core = t.classList.contains('primary') ? ' core' : '';
        html += '<div class="rm-row"><div class="rm-cell ' + side + '"><span class="rm-dot"></span>'
          + '<button type="button" class="rm-node' + core + '" data-key="' + t.dataset.modal + '">'
          + escH(title) + '</button></div></div>';
      });
      html += '</div>';
    });
    html += '</div><div class="rm-foot">Sections run top to bottom. Within a section the order is a suggestion, not a rule.</div>';
    rm.innerHTML = html;
    groups[0].insertAdjacentElement('beforebegin', rm);
    rm.addEventListener('click', e => {
      const b = e.target.closest('.rm-node');
      if (b) openModal(b.dataset.key);
    });
    const bar = panel.querySelector('.cheat-toolbar');
    if (bar && !bar.querySelector('.rm-switch')) {
      const sw = document.createElement('div');
      sw.className = 'rm-switch';
      sw.innerHTML = '<button type="button" data-v="rm">Roadmap</button><button type="button" data-v="grid">Grid</button>';
      bar.appendChild(sw);
      const apply = v => {
        panel.classList.toggle('rm-mode', v === 'rm');
        sw.querySelectorAll('button').forEach(b2 => b2.classList.toggle('on', b2.dataset.v === v));
        try { localStorage.setItem('narissa-da-view-' + panelId, v); } catch (err) {}
      };
      sw.addEventListener('click', e => { const b2 = e.target.closest('button'); if (b2) apply(b2.dataset.v); });
      let v = 'rm';
      try { v = localStorage.getItem('narissa-da-view-' + panelId) || 'rm'; } catch (err) {}
      apply(v);
    }
    refreshProgress();
  }

  function refreshProgress() {
    allTiles.forEach(t => t.classList.toggle('is-learned', !!learned[t.dataset.modal]));
    document.querySelectorAll('.rm-node').forEach(n => n.classList.toggle('is-learned', !!learned[n.dataset.key]));
    document.querySelectorAll('.tab-panel').forEach(p => {
      const tiles = Array.from(p.querySelectorAll('.cheat-tile'));
      const done = tiles.filter(t => learned[t.dataset.modal]).length;
      let bar = p.querySelector('.progress-strip');
      if (!bar) {
        const tb = p.querySelector('.cheat-toolbar');
        if (!tb) return;
        bar = document.createElement('div');
        bar.className = 'progress-strip';
        bar.innerHTML = '<div class="ps-text"></div><div class="ps-track"><div class="ps-fill"></div></div>';
        tb.insertAdjacentElement('afterend', bar);
      }
      const pct = tiles.length ? Math.round(done / tiles.length * 100) : 0;
      bar.querySelector('.ps-text').innerHTML = '<strong>' + done + ' / ' + tiles.length + '</strong> topics marked as learned';
      bar.querySelector('.ps-fill').style.width = pct + '%';
    });
    if (typeof updateIndex === 'function') updateIndex();
  }

  // ---- search index (plain text of every popup) so search finds words inside popups too
  const searchIndex = {};
  Object.keys(CONTENT).forEach(k => { const d = CONTENT[k]; searchIndex[k] = ((d.title || '') + ' ' + (d.tag || '')).toLowerCase(); });
  let _siState = 0;
  function loadSearchIndex() {
    if (_siState) return; _siState = 1;
    fetch('search-index.json?v=20261013').then(r => { if (!r.ok) throw 0; return r.json(); }).then(j => {
      Object.keys(j).forEach(k => { const d = CONTENT[k] || {}; searchIndex[k] = ((d.title || '') + ' ' + (d.tag || '') + ' ' + j[k]).toLowerCase(); });
      _siState = 2;
      const el = document.getElementById('tileSearch');
      if (el && el.value) el.dispatchEvent(new Event('input'));
    }).catch(() => { _siState = 0; });
  }
  window.__loadSearchIndex = loadSearchIndex;

  // ---- copy helper
  function copyText(text, btn) {
    const done = () => {
      const old = btn.dataset.label || btn.textContent;
      btn.dataset.label = old;
      btn.textContent = '✓ Copied';
      btn.classList.add('copied');
      setTimeout(() => { btn.textContent = old; btn.classList.remove('copied'); }, 1400);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
    } else { fallbackCopy(text, done); }
  }
  function fallbackCopy(text, cb) {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); cb();
  }

  function esc(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function highlightBrackets(s) { return esc(s).replace(/\[([^\]]+)\]/g, '<mark>[$1]</mark>'); }

  function promptLabHTML(key) {
    const list = buildPrompts(key);
    if (!list) return '';
    let html = '<div class="prompt-lab"><div class="pl-head"><span class="pl-icon">✨</span><div><div class="pl-title">AI Prompt Lab</div><div class="pl-sub">Copy a prompt into Claude or any AI assistant. Replace the <mark>[highlighted]</mark> parts with your own details, and never paste confidential or personal data.</div></div></div>';
    html += '<div class="pl-tabs" role="tablist">';
    list.forEach((p, i) => { html += '<button class="pl-tab' + (i === 1 ? ' active' : '') + '" data-pl="' + p.id + '" role="tab">' + p.icon + ' ' + p.label + '</button>'; });
    html += '</div>';
    list.forEach((p, i) => {
      html += '<div class="pl-card' + (i === 1 ? ' active' : '') + '" data-pl-card="' + p.id + '">' +
        '<div class="pl-card-top"><span class="pl-hint">' + p.hint + '</span><button class="copy-btn pl-copy" data-copy-prompt="' + p.id + '">📋 Copy prompt</button></div>' +
        '<div class="pl-text">' + highlightBrackets(p.text) + '</div></div>';
    });
    html += '<div class="pl-foot">⚠️ AI can sound confident and still be wrong. Verify numbers, formulas and sources before you use them.</div></div>';
    return html;
  }

  function currentKey() { return overlay.dataset.key || ''; }

