  // glossary tooltips: wrap the first use of each curated term in a popup
  const glTip = document.createElement('div');
  glTip.id = 'glTip'; glTip.setAttribute('role', 'tooltip'); glTip.hidden = true;
  document.body.appendChild(glTip);
  let glCur = null, glAt = 0, glTouch = 0;
  document.addEventListener('touchend', () => { glTouch = Date.now(); }, true);
  const GL_RE = GLOSSARY.map(g => new RegExp(g[1], g[2] ? '' : 'i'));
  const GL_SKIP = 'code, pre, .code-block, svg, .raw-data, .prompt-lab, h1, h2, h3, h4, th, button, a, .co-label, .gl-term, .gl-strip, .svg-label';
  function glTextNodes() {
    const out = [];
    const w = document.createTreeWalker(modalBody, NodeFilter.SHOW_TEXT, {
      acceptNode(n) {
        if (!n.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
        return n.parentElement && n.parentElement.closest(GL_SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
      }
    });
    let n; while ((n = w.nextNode())) out.push(n);
    return out;
  }
  function glHide() { glTip.hidden = true; if (glCur) glCur.classList.remove('gl-open'); glCur = null; }
  function glShow(el) {
    if (glCur && glCur !== el) glCur.classList.remove('gl-open');
    glCur = el; glAt = Date.now(); el.classList.add('gl-open');
    const g = GLOSSARY[+el.dataset.gl];
    glTip.innerHTML = '';
    const b = document.createElement('strong'); b.textContent = g[0];
    glTip.appendChild(b); glTip.appendChild(document.createTextNode(g[3]));
    glTip.hidden = false;
    const r = el.getBoundingClientRect(), tw = glTip.offsetWidth, th = glTip.offsetHeight;
    let x = Math.max(8, Math.min(r.left + r.width / 2 - tw / 2, window.innerWidth - tw - 8));
    let y = r.bottom + 8; if (y + th > window.innerHeight - 8) y = Math.max(8, r.top - th - 8);
    glTip.style.left = x + 'px'; glTip.style.top = y + 'px';
    el.setAttribute('aria-describedby', 'glTip');
  }
  modalBody.addEventListener('mouseover', e => { const t = e.target.closest && e.target.closest('.gl-term'); if (t) glShow(t); });
  modalBody.addEventListener('mouseout', e => { const t = e.target.closest && e.target.closest('.gl-term'); if (t && !t.contains(e.relatedTarget) && Date.now() - glTouch > 800) glHide(); });
  modalBody.addEventListener('focusin', e => { const t = e.target.closest && e.target.closest('.gl-term'); if (t) glShow(t); });
  modalBody.addEventListener('focusout', e => { if (e.target.closest && e.target.closest('.gl-term')) glHide(); });
  modalBody.addEventListener('click', e => {
    const t = e.target.closest && e.target.closest('.gl-term');
    if (!t) return;
    if (glCur === t && !glTip.hidden && Date.now() - glAt > 700 && e.pointerType === 'touch') glHide(); else glShow(t);
  });
  modalBody.addEventListener('keydown', e => {
    const t = e.target.closest && e.target.closest('.gl-term');
    if (t && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); glShow(t); }
  });
  document.addEventListener('pointerdown', e => { if (!glTip.hidden && !(e.target.closest && e.target.closest('.gl-term'))) glHide(); });
  modalBody.addEventListener('scroll', () => { if (Date.now() - glAt > 500) glHide(); }, { passive: true });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && !glTip.hidden) { glHide(); e.stopImmediatePropagation(); } }, true);

  function glossaryDecorate() {
    glHide();
    const title = (modalTitle.textContent || '');
    const found = [];
    GLOSSARY.forEach((g, i) => {
      if (GL_RE[i].test(title)) return;
      found.push(i);
    });
    const hits = [];
    const nodes = glTextNodes();
    found.forEach(i => {
      for (const n of nodes) {
        const m = GL_RE[i].exec(n.nodeValue);
        if (m) { hits.push({ i, pos: nodes.indexOf(n) * 1e5 + m.index }); break; }
      }
    });
    hits.sort((a, b) => a.pos - b.pos);
    const chosen = hits.slice(0, 7).map(h => h.i);
    const used = [];
    chosen.forEach(i => {
      for (const n of glTextNodes()) {
        const m = GL_RE[i].exec(n.nodeValue);
        if (!m) continue;
        const after = n.splitText(m.index);
        const rest = after.splitText(m[0].length);
        const sp = document.createElement('span');
        sp.className = 'gl-term'; sp.tabIndex = 0; sp.dataset.gl = i;
        sp.textContent = m[0];
        after.parentNode.replaceChild(sp, after);
        used.push(i);
        break;
      }
    });
    if (used.length) {
      const d = document.createElement('details');
      d.className = 'gl-strip';
      const s = document.createElement('summary'); s.textContent = '📖 Key terms in this topic (' + used.length + ')';
      d.appendChild(s);
      const dl = document.createElement('dl');
      used.forEach(i => {
        const dt = document.createElement('dt'); dt.textContent = GLOSSARY[i][0];
        const dd = document.createElement('dd'); dd.textContent = GLOSSARY[i][3];
        dl.appendChild(dt); dl.appendChild(dd);
      });
      d.appendChild(dl); modalBody.appendChild(d);
    }
  }

  function decorateBody(key) {
    glossaryDecorate();
    // copy buttons on code blocks
    modalBody.querySelectorAll('.code-block').forEach(cb => {
      if (cb.parentElement.classList.contains('code-wrap')) return;
      const wrap = document.createElement('div');
      wrap.className = 'code-wrap';
      cb.parentNode.insertBefore(wrap, cb);
      wrap.appendChild(cb);
      const b = document.createElement('button');
      b.className = 'copy-btn code-copy'; b.type = 'button'; b.textContent = 'Copy';
      b.addEventListener('click', () => copyText(cb.innerText, b));
      wrap.appendChild(b);
    });
    // sample data
    const rdHTML = rawDataHTML(key);
    if (rdHTML) {
      const rh = document.createElement('div');
      rh.innerHTML = rdHTML;
      modalBody.appendChild(rh.firstChild);
      const rb = modalBody.querySelector('[data-rd-copy]');
      if (rb) rb.addEventListener('click', () => copyText(rawDataText(key), rb));
    }
    // prompt lab
    const labHTML = promptLabHTML(key);
    if (labHTML) {
      const holder = document.createElement('div');
      holder.innerHTML = labHTML;
      modalBody.appendChild(holder.firstChild);
      const lab = modalBody.querySelector('.prompt-lab');
      const list = buildPrompts(key);
      lab.querySelectorAll('.pl-tab').forEach(tab => tab.addEventListener('click', () => {
        lab.querySelectorAll('.pl-tab').forEach(x => x.classList.remove('active'));
        lab.querySelectorAll('.pl-card').forEach(x => x.classList.remove('active'));
        tab.classList.add('active');
        lab.querySelector('[data-pl-card="' + tab.dataset.pl + '"]').classList.add('active');
      }));
      lab.querySelectorAll('[data-copy-prompt]').forEach(btn => btn.addEventListener('click', () => {
        const p = list.find(x => x.id === btn.dataset.copyPrompt);
        copyText(p.text, btn);
      }));
    }
  }

  function updateNav(key) {
    const tile = tileFor(key);
    const siblings = tile ? Array.from(panelOf(tile).querySelectorAll('.cheat-tile')).map(t => t.dataset.modal) : tileOrder;
    const i = siblings.indexOf(key);
    const prev = modalEl.querySelector('.nav-prev');
    const next = modalEl.querySelector('.nav-next');
    const pos = modalEl.querySelector('.nav-pos');
    prev.disabled = i <= 0;
    next.disabled = i < 0 || i >= siblings.length - 1;
    prev.dataset.target = i > 0 ? siblings[i - 1] : '';
    next.dataset.target = (i >= 0 && i < siblings.length - 1) ? siblings[i + 1] : '';
    pos.textContent = (i + 1) + ' / ' + siblings.length;
    const lb = modalEl.querySelector('.learn-btn');
    lb.classList.toggle('on', !!learned[key]);
    lb.textContent = learned[key] ? '✓ Learned' : '☐ Mark as learned';
  }

  // build nav bar + takeaway container once
  (function buildChrome() {
    modalFoot.innerHTML = '';
    modalFoot.classList.add('modal-foot-nav');
    modalFoot.innerHTML =
      '<button class="nav-btn nav-prev" type="button">← Previous</button>' +
      '<div class="nav-mid"><button class="learn-btn" type="button">☐ Mark as learned</button>' +
      '<button class="print-btn" type="button">🖨 Print</button><span class="nav-pos"></span></div>' +
      '<button class="nav-btn nav-next" type="button">Next →</button>';
    modalFoot.querySelector('.nav-prev').addEventListener('click', e => { const t = e.currentTarget.dataset.target; if (t) openModal(t); });
    modalFoot.querySelector('.nav-next').addEventListener('click', e => { const t = e.currentTarget.dataset.target; if (t) openModal(t); });
    modalFoot.querySelector('.learn-btn').addEventListener('click', () => {
      const k = currentKey(); if (!k) return;
      if (learned[k]) delete learned[k]; else learned[k] = 1;
      saveLearned(); refreshProgress(); updateNav(k);
    });
    modalFoot.querySelector('.print-btn').addEventListener('click', () => {
      document.body.classList.add('printing-modal');
      window.print();
      setTimeout(() => document.body.classList.remove('printing-modal'), 400);
    });
    // make nav helpers reachable via modalEl.querySelector
  })();

