  const REFERENCE_METHODS = [{"id":"f-base","kind":"forecast","family":"Baseline","name":"Naïve, seasonal naïve & drift","summary":"Three essential reference forecasts: repeat the last value, repeat the last matching season, or extend average historical change.","fit":"Use as the minimum benchmark for every forecasting project. Seasonal naïve is particularly useful when a calendar pattern repeats.","avoid":"Drift extrapolates indefinitely; it can fail after a regime shift. A seasonal baseline cannot anticipate a promotion.","data":"Time-ordered observations; a known seasonal period for seasonal naïve.","controls":"Season length; training window; whether a drift assumption is defensible.","check":"Score the exact operational horizon, not only next-step errors.","example":"Weekly retail demand: compare against the same week last year before adding a complex model.","tools":"Python: StatsForecast Naive / SeasonalNaive / RandomWalkWithDrift. R: fable NAIVE / SNAIVE / RW.","source":"https://otexts.com/fpp3/simple-methods.html"},{"id":"f-ets","kind":"forecast","family":"Statistical","name":"Exponential smoothing · SES, Holt, ETS","summary":"Update level, trend, and seasonal components as new observations arrive; more recent evidence receives greater influence.","fit":"SES for a changing level; Holt for trend; seasonal ETS for repeating demand. Damped trends limit long-range extrapolation.","avoid":"Abrupt interventions or driver effects require additional modeling. Multiplicative components need positive values.","data":"A regular time series; enough repeated seasons to assess stability.","controls":"Error / trend / season structure, damping, smoothing rates, additive versus multiplicative effects.","check":"Rolling-origin errors and interval coverage; inspect residual seasonality.","example":"Monthly service workload: compare damped ETS with seasonal naïve.","tools":"Python: StatsForecast AutoETS, statsmodels ETSModel. R: fable ETS.","source":"https://otexts.com/fpp3/ets.html"},{"id":"f-arima","kind":"forecast","family":"Statistical","name":"ARIMA, SARIMA & AutoARIMA","summary":"Model dependence on past values and past errors after appropriate differencing; SARIMA adds seasonal dependence.","fit":"A few well-observed series with useful serial correlation.","avoid":"Do not add differencing automatically or fit large orders to short histories. Automated selection is not future validation.","data":"Regular timestamps; explicit missing-period handling; seasonal period m.","controls":"Nonseasonal (p,d,q), seasonal (P,D,Q), drift, transformation, search bounds.","check":"Check residual autocorrelation, stability, and rolling-origin performance at all needed horizons.","example":"Monthly subscriptions: test SARIMA with m=12 against ETS and seasonal naïve.","tools":"Python: StatsForecast AutoARIMA, statsmodels SARIMAX. R: fable ARIMA.","source":"https://otexts.com/fpp3/seasonal-arima.html"},{"id":"f-xreg","kind":"forecast","family":"Driver-based","name":"Dynamic regression / SARIMAX","summary":"Combine explanatory variables with time-dependent errors. A forecast depends on both estimated relationships and future driver inputs.","fit":"Calendar, planned prices, promotions, or externally forecast weather matter.","avoid":"A future feature not available at forecast issuance creates leakage. A what-if prediction does not prove a causal effect.","data":"Target history, aligned drivers, and a documented source for every future driver.","controls":"Lagged effects, ARIMA errors, interactions, driver scenarios.","check":"Backtest with historical driver forecasts or as-of information, not realized future values.","example":"Staffing: forecast calls using holidays and scheduled campaigns; supply low/base/high campaign scenarios.","tools":"Python: statsmodels SARIMAX. R: fable ARIMA with regressors.","source":"https://otexts.com/fpp3/dynamic.html"},{"id":"f-mstl","kind":"forecast","family":"Statistical","name":"MSTL, Fourier regression & TBATS","summary":"Separate or represent multiple seasonal cycles, then forecast the remaining dynamics. These are related options, not interchangeable algorithms.","fit":"Hourly demand with daily and weekly cycles; long or overlapping seasonality.","avoid":"A fixed seasonal pattern may drift; complex specifications increase tuning and compute.","data":"Correctly spaced timestamps, time-zone/DST policy, enough cycles for each seasonality.","controls":"Season periods, decomposition windows, Fourier harmonics, trend/ARMA specification.","check":"Check by hour, weekday, holiday, and horizon; fit decomposition inside each training window.","example":"Electricity use: compare a 24/168-hour seasonal model with lag-feature boosting.","tools":"Python: StatsForecast MSTL; R: forecast tbats; Fourier regressors with a regression model.","source":"https://otexts.com/fpp3/complexseasonality.html"},{"id":"f-prophet","kind":"forecast","family":"Driver-based","name":"Prophet","summary":"An additive forecasting framework with trend changes, seasonal terms, and optional holiday or regressor effects.","fit":"Business time series where calendar effects and trend-change assumptions are useful to inspect.","avoid":"It is not automatically better than ETS or ARIMA. Sharp shocks and short histories still cause failures.","data":"Timestamp and target columns; future values for added regressors.","controls":"Changepoint flexibility, seasonal flexibility, holiday windows, growth assumptions.","check":"Use rolling cutoffs and compare against simple baselines; inspect implausible extrapolation.","example":"Daily sign-ups: investigate weekly patterns and campaigns with a held-out final period.","tools":"Python / R: Prophet. Record holidays and regressor availability in the model brief.","source":"https://facebook.github.io/prophet/docs/quick_start.html"},{"id":"f-croston","kind":"forecast","family":"Specialized","name":"Intermittent demand · Croston, SBA, TSB","summary":"Croston-style methods separate nonzero demand sizes from arrival intervals; variants address bias or changing arrival probability.","fit":"Spare parts or SKUs with many zero-demand periods.","avoid":"Zeros caused by stockouts are censored demand, not evidence of no customer need. Standard Croston does not supply a full predictive distribution.","data":"Demand history, product status, availability, and lead times.","controls":"Smoothing of size / interval / occurrence; obsolescence handling; aggregation frequency.","check":"Evaluate lead-time demand and inventory outcomes as well as point error. Avoid MAPE on zero demand.","example":"Repair parts: compare SBA and TSB, especially when items become obsolete.","tools":"Python: StatsForecast CrostonClassic / CrostonSBA / TSB.","source":"https://otexts.com/fpp3/counts.html"},{"id":"f-ml","kind":"forecast","family":"Machine learning","name":"Global lag-feature ML · boosted trees / forests","summary":"Turn history into supervised rows using lagged targets, rolling summaries, calendar variables, and available covariates. Train across related series.","fit":"Many stores or products share patterns and have useful nonlinear drivers.","avoid":"Unshifted rolling statistics leak the target. Recursive forecasts accumulate error; direct models need horizon-specific training.","data":"Series ID, ordered time, target, and features available at each origin.","controls":"Lags, rolling windows, direct versus recursive strategy, tree complexity, group features.","check":"Split by time; consider unseen-series tests if new products matter. Audit each feature as-of time.","example":"Retail panel: lag-1/7/28 demand plus planned promotion flags, compared with seasonal naïve.","tools":"Python: MLForecast with LightGBM / XGBoost / scikit-learn estimators.","source":"https://nixtlaverse.nixtla.io/mlforecast/index.html"},{"id":"f-neural","kind":"forecast","family":"Machine learning","name":"Neural forecasting · N-BEATS, NHITS, TFT, PatchTST","summary":"Learn nonlinear temporal patterns, often jointly across many series. Architectures differ in decomposition, covariate support, and attention.","fit":"Large related datasets and meaningful multi-horizon complexity.","avoid":"Few observations, limited compute, or weak baselines make large networks difficult to justify.","data":"Clean aligned series; train/validation windows; explicit known-future versus historical features.","controls":"Input window, horizon, architecture, scaling, learning rate, quantile or distributional loss.","check":"Evaluate multiple origins and seeds; compare latency, error, and interval calibration against simpler methods.","example":"Many related demand series: test NHITS and TFT only after global tree and statistical baselines.","tools":"Python: NeuralForecast. Consult each architecture for supported covariates.","source":"https://nixtlaverse.nixtla.io/neuralforecast/docs/getting-started/introduction.html"},{"id":"f-foundation","kind":"forecast","family":"Machine learning","name":"Pretrained time-series models · Chronos family","summary":"Reuse a model pretrained on many time series for zero-shot or adapted forecasting. This is distinct from asking a chat model to invent future numbers.","fit":"Fast candidate generation across many series; limited project-specific training effort.","avoid":"Domain mismatch, model limits, licensing, and inference costs still matter. Pretraining does not guarantee local accuracy.","data":"Context windows in the required format; document scaling, missing values, covariates, and output quantiles.","controls":"Checkpoint, context length, horizon, adaptation, device / batching.","check":"Use the identical cutoff and horizon as your own baselines; check coverage and operational cost.","example":"A new demand portfolio: benchmark an available Chronos checkpoint against ETS and seasonal naïve.","tools":"Amazon Science Chronos repository; pin checkpoint and package versions.","source":"https://github.com/amazon-science/chronos-forecasting"},{"id":"f-hierarchy","kind":"forecast","family":"Specialized","name":"Hierarchical reconciliation · bottom-up / MinT","summary":"Make forecasts coherent across levels such as store → region → total. Reconciliation combines base forecasts with aggregation constraints.","fit":"Planning needs totals and detailed forecasts that add up.","avoid":"Independently adjusted totals can conflict with item forecasts. Sparse bottom-level series may make simple bottom-up forecasts noisy.","data":"An aggregation structure, base forecasts, and residual information for covariance-based methods.","controls":"Aggregation matrix, reconciliation method, covariance estimation, nonnegativity.","check":"Measure accuracy at every business level and verify exact additivity.","example":"Regional demand: compare bottom-up with MinT and evaluate both SKU and total-level results.","tools":"Python: HierarchicalForecast. R: fabletools reconcile / min_trace.","source":"https://otexts.com/fpp3/reconciliation.html"},{"id":"f-ensemble","kind":"forecast","family":"Specialized","name":"Forecast combinations & ensembles","summary":"Combine forecasts whose errors differ. A simple average is a valuable candidate before fitting elaborate weights.","fit":"Several credible models perform similarly but fail in different periods.","avoid":"Weights optimized on the test period leak outcomes. Highly correlated models offer less diversification.","data":"Out-of-fold predictions from each candidate at matching origins and horizons.","controls":"Equal versus validation-learned weights; nonnegative constraints; horizon-specific weighting.","check":"Compare the combination with its strongest component across multiple origins.","example":"Combine ETS, SARIMA, and lag-based boosting; fit any weights on validation predictions only.","tools":"R / Python: average aligned predictions; use constrained regression if justified.","source":"https://otexts.com/fpp3/combinations.html"},{"id":"f-state","kind":"forecast","family":"Statistical","name":"Structural state-space / local-level models","summary":"Represent evolving hidden components such as level and slope, with separate observation and state uncertainty.","fit":"A process changes gradually and the component interpretation matters.","avoid":"A flexible state model can absorb noise as trend. Missing observations require supported handling, not casual zero filling.","data":"Time-ordered observations; justified components and error assumptions.","controls":"Level / slope dynamics, seasonal states, observation variance, intervention terms.","check":"Inspect innovations, uncertainty, and response to structural breaks; compare simpler ETS.","example":"Sensor workload: allow the underlying level to evolve while separating measurement noise.","tools":"Python: statsmodels UnobservedComponents / state-space tools.","source":"https://www.statsmodels.org/stable/statespace.html"},{"id":"f-var","kind":"forecast","family":"Statistical","name":"VAR / VECM","summary":"Model several interacting time series jointly. VECM adds a cointegration structure for certain nonstationary systems.","fit":"A small set of related series and enough observations to estimate lagged cross-dependencies.","avoid":"Many variables create many parameters. Predictive lead-lag relationships do not establish causality.","data":"Aligned series; stationarity or cointegration assessment; adequate history for chosen dimension.","controls":"Lag order, deterministic terms, transformation, cointegration rank for VECM.","check":"Check stability and residuals; compare each target with univariate alternatives.","example":"Operational demand and capacity: assess whether joint forecasting improves held-out accuracy.","tools":"Python: statsmodels VAR / VECM.","source":"https://www.statsmodels.org/stable/vector_ar.html"},{"id":"f-quantile","kind":"forecast","family":"Uncertainty","name":"Quantile forecasts & prediction intervals","summary":"An output strategy layered on suitable models: forecast percentiles or distributions, not only a single expected value.","fit":"Inventory buffers, staffing reserves, and asymmetric under/overprediction costs.","avoid":"A model-based interval excludes unmodeled shocks. An 80% interval should be assessed over repeated forecasts, not as a guarantee for one event.","data":"Past forecast errors or a fitted probabilistic model, with horizon-specific evaluation.","controls":"Quantile levels, distribution family, calibration window, dependence assumptions.","check":"Inspect empirical coverage and width by horizon and segment; use pinball or interval scores.","example":"Staffing: compare median and upper-quantile demand, then evaluate resulting service and idle-capacity costs.","tools":"Probabilistic ETS/ARIMA; quantile boosting; NeuralForecast distributional or quantile losses.","source":"https://otexts.com/fpp3/prediction-intervals.html"},{"id":"p-linear","kind":"predict","family":"Interpretable","name":"Linear, Ridge, Lasso & Elastic Net","summary":"Predict a numeric outcome from additive feature effects; regularization constrains coefficients to improve generalization.","fit":"A transparent numeric baseline, including high-dimensional correlated features.","avoid":"Unmodeled nonlinear effects and extrapolation can fail. Coefficients are not automatically causal.","data":"Numeric / encoded predictors; preprocessing learned only on training data.","controls":"Penalty strength, L1/L2 balance, interactions, scaling.","check":"Use held-out MAE/RMSE and residual plots; check stability across segments.","example":"Delivery duration from distance, workload, and route features.","tools":"scikit-learn LinearRegression / Ridge / Lasso / ElasticNet.","source":"https://scikit-learn.org/stable/modules/linear_model.html"},{"id":"p-logistic","kind":"predict","family":"Interpretable","name":"Logistic regression","summary":"Map a linear score to a class probability; regularization controls complexity.","fit":"A strong interpretable classification baseline.","avoid":"Default 0.5 decisions may mismatch costs. Nonlinear class boundaries may need feature engineering.","data":"Labeled outcomes and features available before the decision.","controls":"Regularization, class weights, interactions, decision threshold.","check":"Assess discrimination and calibration; set threshold on validation data.","example":"Predict renewal within 30 days from pre-renewal activity.","tools":"scikit-learn LogisticRegression.","source":"https://scikit-learn.org/stable/modules/linear_model.html"},{"id":"p-glm","kind":"predict","family":"Interpretable","name":"GLMs · Poisson, negative binomial, Gamma, Tweedie","summary":"Match the outcome distribution and link function to its support: counts, positive amounts, or other appropriate response types.","fit":"Counts or skewed nonnegative outcomes where ordinary squared-error regression is poorly matched.","avoid":"Poisson equidispersion may fail; distinguish zero inflation from simple overdispersion. Distribution assumptions affect inference and uncertainty.","data":"Correct target support; exposure / offset when observation opportunities differ.","controls":"Family, link, dispersion, interactions, exposure treatment.","check":"Check deviance, residuals, support violations, and held-out errors.","example":"Tickets per customer-month: use exposure rather than treating unequal observation windows as equivalent.","tools":"statsmodels GLM / count models; scikit-learn PoissonRegressor / TweedieRegressor.","source":"https://www.statsmodels.org/stable/glm.html"},{"id":"p-gam","kind":"predict","family":"Interpretable","name":"Generalized additive models · GAMs","summary":"Fit smooth feature-response curves while retaining an additive structure.","fit":"Nonlinear effects that stakeholders need to inspect, such as temperature or tenure curves.","avoid":"Additivity misses interactions unless explicitly included; edge extrapolation can be unstable.","data":"Sufficient coverage across each feature range; suitable outcome family.","controls":"Spline basis size, smoothing penalties, interactions, family/link.","check":"Inspect smooth shapes, residuals, out-of-range behavior, and held-out accuracy.","example":"Estimate support workload as a smooth function of account age and usage.","tools":"statsmodels GLMGam; R mgcv.","source":"https://www.statsmodels.org/stable/gam.html"},{"id":"p-tree","kind":"predict","family":"Tree-based","name":"Decision trees","summary":"Split feature space into rules, then predict a leaf average or class distribution.","fit":"A compact nonlinear rule baseline with readable decision paths.","avoid":"Deep trees overfit and small data changes can alter rules. Numeric regression leaves do not extrapolate trends.","data":"Labeled rows; encoding and missing-value handling supported by the implementation.","controls":"Depth, minimum leaf size, pruning, split criterion.","check":"Compare pruned trees using validation and inspect rare leaves.","example":"Route service requests to likely escalation categories.","tools":"scikit-learn DecisionTreeClassifier / DecisionTreeRegressor.","source":"https://scikit-learn.org/stable/modules/tree.html"},{"id":"p-forest","kind":"predict","family":"Tree-based","name":"Random forests / Extra Trees","summary":"Average many randomized trees to reduce variance.","fit":"Nonlinear tabular baselines with interactions and limited preprocessing.","avoid":"Large forests cost memory; predictions are harder to explain than one tree.","data":"Labeled rows with consistent feature semantics.","controls":"Trees, depth, leaf size, feature sampling.","check":"Use held-out performance and permutation importance; inspect important subgroups.","example":"Predict job completion time from operational features.","tools":"scikit-learn RandomForest / ExtraTrees.","source":"https://scikit-learn.org/stable/modules/ensemble.html"},{"id":"p-boost","kind":"predict","family":"Tree-based","name":"Gradient-boosted trees","summary":"Sequentially add trees that improve the current prediction under a chosen loss.","fit":"Structured tabular data with nonlinear effects.","avoid":"Tuning and leakage can create impressive but unreliable scores.","data":"Train/validation partitions with production-like features.","controls":"Learning rate, iterations, leaf complexity, regularization, early stopping.","check":"Compare to linear and forest baselines using the same splits.","example":"Predict customer churn or order value from mixed business features.","tools":"scikit-learn HistGradientBoosting; XGBoost, LightGBM, CatBoost.","source":"https://scikit-learn.org/stable/modules/ensemble.html"},{"id":"p-svm","kind":"predict","family":"Distance / kernel","name":"Support vector machines · SVC / SVR","summary":"Use margin-based prediction; kernels can represent nonlinear boundaries.","fit":"Small-to-moderate feature datasets; linear variants can suit sparse text.","avoid":"Kernel methods can be expensive on large datasets; scaling and hyperparameters matter.","data":"Scaled numeric features; encoded categories; carefully separated preprocessing.","controls":"C, kernel, gamma; epsilon for SVR.","check":"Tune within cross-validation; calibrate classification scores separately if probabilities drive decisions.","example":"Classify a modest sensor-feature dataset with a nonlinear boundary.","tools":"scikit-learn SVC / LinearSVC / SVR.","source":"https://scikit-learn.org/stable/modules/svm.html"},{"id":"p-knn","kind":"predict","family":"Distance / kernel","name":"k-nearest neighbors","summary":"Predict from nearby examples rather than a compact fitted formula.","fit":"A local-similarity baseline in a meaningful, relatively low-dimensional feature space.","avoid":"Distances degrade in high dimensions; prediction requires neighbor search and feature scaling.","data":"Representative examples and a defensible distance metric.","controls":"k, distance metric, uniform versus distance weights.","check":"Fit scaling on training only; compare performance by dense and sparse regions.","example":"Estimate duration from genuinely similar historical jobs.","tools":"scikit-learn KNeighborsClassifier / KNeighborsRegressor.","source":"https://scikit-learn.org/stable/modules/neighbors.html"},{"id":"p-bayes","kind":"predict","family":"Probabilistic","name":"Naïve Bayes","summary":"Combine feature evidence under conditional independence assumptions.","fit":"Fast text classification and constrained baseline systems.","avoid":"Strong feature dependence can distort probabilities even when classifications are useful.","data":"Appropriate feature distribution: counts, binary indicators, or continuous values.","controls":"Distribution variant, smoothing, priors, vocabulary.","check":"Measure precision/recall and calibration on held-out data.","example":"Tag support-ticket topics using word-count features.","tools":"scikit-learn MultinomialNB / BernoulliNB / GaussianNB.","source":"https://scikit-learn.org/stable/modules/naive_bayes.html"},{"id":"p-neural","kind":"predict","family":"Neural","name":"Neural networks · MLP and task-specific architectures","summary":"Learn layered nonlinear feature transformations; specialized networks address images, text, and sequences.","fit":"Large or complex datasets when learned representations improve on simpler alternatives.","avoid":"Small tabular datasets do not automatically benefit. Optimization, scaling, compute, and reproducibility add work.","data":"Training examples representative of deployment and a separate validation set.","controls":"Architecture, learning rate, regularization, batch size, early stopping.","check":"Compare multiple seeds and simpler baselines; assess calibration, subgroup error, and latency.","example":"An MLP challenger for tabular outcomes; specialized encoders for text or image inputs.","tools":"scikit-learn MLP for tabular baselines; specialized deep-learning frameworks as needed.","source":"https://scikit-learn.org/stable/modules/neural_networks_supervised.html"},{"id":"p-survival","kind":"predict","family":"Specialized","name":"Survival models · Cox, AFT, survival forests","summary":"Model time until an event while accounting for censored cases whose event time is not yet observed.","fit":"Time-to-churn, equipment failure, or completion with incomplete follow-up.","avoid":"Treating censored observations as “never happened” biases ordinary classification or regression. Cox proportional hazards needs assessment.","data":"Event indicator, time origin, follow-up duration, censoring definition, valid covariates.","controls":"Model family, regularization, time-varying effects, competing-risk treatment.","check":"Time-dependent discrimination, calibration, and Brier scores with censoring-aware evaluation.","example":"Estimate retention probability at 30/90/180 days from the account start date.","tools":"scikit-survival; lifelines.","source":"https://scikit-survival.readthedocs.io/en/stable/user_guide/00-introduction.html"},{"id":"p-quantile","kind":"predict","family":"Uncertainty","name":"Quantile regression","summary":"Estimate a conditional percentile rather than the conditional mean.","fit":"Asymmetric costs or a need for ranges across heterogeneous cases.","avoid":"Separately fitted quantiles may cross; quantiles are not automatically calibrated prediction intervals.","data":"A numeric target and feature coverage in important tail regions.","controls":"Quantile level, regularization, linear versus nonlinear model.","check":"Use pinball loss; check coverage and crossing on held-out cases.","example":"Predict the 90th percentile of delivery time for a service promise.","tools":"scikit-learn QuantileRegressor; quantile tree boosting.","source":"https://scikit-learn.org/stable/auto_examples/linear_model/plot_quantile_regression.html"},{"id":"p-ordinal","kind":"predict","family":"Interpretable","name":"Ordinal & multinomial classification","summary":"Ordinal models use an ordered outcome structure; multinomial models handle categories without a natural order.","fit":"Ratings such as low/medium/high versus unordered product classes.","avoid":"Numeric class codes do not imply equal spacing. Ordered-logit proportional-odds assumptions may fail.","data":"Explicit category order where justified, plus enough observations per class.","controls":"Link function, regularization, proportional versus nonproportional effects.","check":"Inspect per-class recall, calibration, and costs of near versus distant mistakes.","example":"Predict ordered satisfaction levels without treating 1→2 and 4→5 as equal numeric increments.","tools":"statsmodels OrderedModel; scikit-learn multinomial logistic regression.","source":"https://www.statsmodels.org/stable/examples/notebooks/generated/ordinal_regression.html"},{"id":"p-uplift","kind":"predict","family":"Specialized","name":"Uplift / treatment-effect models","summary":"Estimate how an intervention changes an outcome rather than who is simply likely to have that outcome.","fit":"Choosing whom to contact or treat when incremental impact matters.","avoid":"Observational treatment is confounded unless identification assumptions are justified. Prediction accuracy alone is not causal validation.","data":"Treatment, outcomes, pre-treatment covariates; ideally randomized assignment and adequate overlap.","controls":"S/T/X-learner choice, nuisance models, treatment propensity, cross-fitting where appropriate.","check":"Use held-out treatment/control evidence and policy value; examine overlap and uncertainty.","example":"Retention offers: distinguish customers who would stay anyway from those helped by the offer.","tools":"EconML; randomized experiments for credible evaluation.","source":"https://www.pywhy.org/EconML/spec/estimation/metalearners.html"},{"id":"p-anomaly","kind":"predict","family":"Specialized","name":"Anomaly detection · Isolation Forest / LOF","summary":"Find unusual observations when reliable event labels are scarce. Novelty detection and outlier detection have different training assumptions.","fit":"Triage and monitoring, not automatic proof of fraud or failure.","avoid":"Rare is not the same as harmful. Unsupervised scores need domain review and threshold evaluation.","data":"A clear reference population; representative normal behavior; labeled audits if available.","controls":"Contamination assumptions, neighborhood size, score threshold.","check":"Review precision at the operational alert budget and investigate drift.","example":"Surface unusual transactions for analyst review with recorded dispositions.","tools":"scikit-learn IsolationForest / LocalOutlierFactor / OneClassSVM.","source":"https://scikit-learn.org/stable/modules/outlier_detection.html"},{"id":"p-gp","kind":"predict","family":"Probabilistic","name":"Gaussian process regression","summary":"Use a kernel to describe similarity and infer a predictive distribution.","fit":"Small datasets, smooth functions, and uncertainty-aware interpolation.","avoid":"Exact methods scale poorly with sample size. Kernel assumptions determine behavior away from observations.","data":"Scaled features; meaningful distances; observation-noise assumptions.","controls":"Kernel components, length scales, noise, optimizer bounds.","check":"Check predictive intervals and errors away from densely sampled regions.","example":"Predict the response of a small engineering experiment and decide where to sample next.","tools":"scikit-learn GaussianProcessRegressor.","source":"https://scikit-learn.org/stable/modules/gaussian_process.html"}];
const refEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let referenceFocus='';
function refTable(heads,rows){return '<div class="ref-table"><table><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function refDownload(name,text,mime='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openReference(key,method=''){referenceFocus=method;const target='#12/'+key;if(location.hash===target){openModal(key)}else location.hash=target;}
function mountReferenceTools(){
 modalBody.querySelectorAll('[data-ref-open]').forEach(b=>b.addEventListener('click',()=>openReference(b.dataset.refOpen)));
 const atlas=modalBody.querySelector('.ref-atlas');if(atlas)mountMethodAtlas(atlas);
 if(modalBody.querySelector('.ref-finder'))mountMethodFinder();
 if(modalBody.querySelector('#forecast-lab'))mountForecastLab();
 if(modalBody.querySelector('#threshold-lab'))mountThresholdLab();
 if(modalBody.querySelector('#model-brief'))mountModelBrief();
}
function mountMethodAtlas(atlas){
 const list=atlas.querySelector('.method-list'),search=atlas.querySelector('.method-search'),family=atlas.querySelector('.method-family'),status=atlas.querySelector('.method-count'),comparison=atlas.querySelector('.method-comparison');
 const all=REFERENCE_METHODS.filter(m=>m.kind===atlas.dataset.kind),selected=new Set();
 const renderCompare=()=>{if(!selected.size){comparison.innerHTML='';return}const chosen=all.filter(m=>selected.has(m.id));comparison.innerHTML='<h4>Compare your shortlist</h4>'+refTable(['Decision',...chosen.map(m=>refEscape(m.name))],[['Good fit',...chosen.map(m=>refEscape(m.fit))],['Watch out',...chosen.map(m=>refEscape(m.avoid))],['Data needed',...chosen.map(m=>refEscape(m.data))],['Validation',...chosen.map(m=>refEscape(m.check))],['Implementation',...chosen.map(m=>refEscape(m.tools))]])+'<p class="ref-small">Selection is temporary in this popup. Record the final rationale in your project brief.</p>';};
 const render=()=>{
  const query=search.value.toLowerCase().trim();const shown=all.filter(m=>(!family.value||m.family===family.value)&&(!query||Object.values(m).join(' ').toLowerCase().includes(query)));status.textContent=shown.length+' of '+all.length+' methods · '+selected.size+' selected';
  list.innerHTML=shown.length?shown.map(m=>`<article class="method-item" data-method="${m.id}"><div class="method-select"><label><input type="checkbox" value="${m.id}" ${selected.has(m.id)?'checked':''}> Compare</label><span>${refEscape(m.family)}</span></div><details class="method-detail"><summary><strong>${refEscape(m.name)}</strong><span>${refEscape(m.summary)}</span></summary><dl>${[['Use when',m.fit],['Reconsider when',m.avoid],['Data & assumptions',m.data],['Controls to tune',m.controls],['Validation & diagnostics',m.check],['Example project',m.example],['Implementation options',m.tools]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+refEscape(v)+'</dd></div>').join('')}</dl><a class="method-source" href="${m.source}" target="_blank" rel="noopener noreferrer">Technical reference ↗</a></details></article>`).join(''):'<p class="ref-empty">No matching methods. Try a broader term or clear the family filter.</p>';
  list.querySelectorAll('input[type=checkbox]').forEach(cb=>cb.addEventListener('change',()=>{if(cb.checked&&selected.size>=3){cb.checked=false;status.textContent='Compare up to three methods. Uncheck one to choose another.';return}if(cb.checked)selected.add(cb.value);else selected.delete(cb.value);status.textContent=shown.length+' of '+all.length+' methods · '+selected.size+' selected';renderCompare();}));
 };
 search.addEventListener('input',render);family.addEventListener('change',render);atlas.querySelector('.clear-methods').addEventListener('click',()=>{search.value='';family.value='';render();search.focus()});render();
 if(referenceFocus){const card=[...list.querySelectorAll('[data-method]')].find(e=>e.dataset.method===referenceFocus);if(card)card.querySelector('details').open=true;referenceFocus='';}
}
function mountMethodFinder(){
 const target=modalBody.querySelector('#finder-target'),pattern=modalBody.querySelector('#finder-pattern'),result=modalBody.querySelector('#finder-result');
 const update=()=>{let ids,reason,validation;const t=target.value,p=pattern.value;
  if(t==='forecast'){
   const choices={regular:[['f-base','f-ets','f-arima'],'Begin with simple temporal baselines and compact statistical models.'],seasonal:[['f-base','f-ets','f-arima'],'Compare a seasonal baseline with models that can update trend and seasonal behavior.'],multiple:[['f-base','f-mstl','f-ml'],'Represent each relevant seasonal cycle; verify the seasonal baseline uses the right period.'],sparse:[['f-base','f-croston','f-ml'],'Separate no-demand periods from unavailable stock and evaluate cumulative lead-time demand.'],drivers:[['f-base','f-xreg','f-ml'],'Require an as-of source for every driver used in the forecast horizon.'],many:[['f-ml','f-neural','f-foundation'],'Shared learning may help related series; still benchmark against per-series seasonal naïve / ETS.'],explain:[['f-base','f-ets','f-xreg'],'Favor interpretable components and explicit driver assumptions before adding complexity.']};[ids,reason]=choices[p];validation='Rolling-origin evaluation at the real forecast horizon; report errors by series and horizon. Evaluate intervals and lead-time decisions when relevant.';
  }else{
   const choices={number:[['p-linear',p==='explain'?'p-gam':'p-boost','p-quantile'],'Compare a numeric baseline with nonlinear structure and tail-aware predictions.'],class:[['p-logistic',p==='explain'?'p-tree':'p-boost','p-bayes'],'Start with logistic regression; use boosted trees for nonlinear tabular patterns. Naïve Bayes is mainly a cheap text/count-feature alternative.'],count:[['p-glm','p-gam','p-boost'],'Respect nonnegative counts and unequal exposure; compare suitable count losses or families.'],survival:[['p-survival'],'Use censoring-aware time-to-event methods rather than labeling unfinished cases as negatives.'],uplift:[['p-uplift'],'An intervention-effect question needs causal identification, not just a high-probability score.'],anomaly:[['p-anomaly'],'Begin with a review queue and labeled audits; unusual does not automatically mean harmful.']};[ids,reason]=choices[t];validation='Use time-based evaluation for future cases and group-held-out evaluation for new entities. For genuinely independent cases, a random/stratified split can be appropriate.';
  }
  result.innerHTML='<span class="ref-eyebrow">RECOMMENDED STARTING COMPARISON</span><p>'+refEscape(reason)+'</p><div class="finder-candidates">'+ids.map(id=>{const m=REFERENCE_METHODS.find(x=>x.id===id);return '<button type="button" data-method-target="'+id+'"><strong>'+refEscape(m.name)+'</strong><span>'+refEscape(m.family)+' · Open reference →</span></button>'}).join('')+'</div><p><strong>Validation:</strong> '+refEscape(validation)+'</p><p class="ref-small">Heuristic shortlist, not an automatic model selection result. Inspect the assumptions in each reference.</p>';
  result.querySelectorAll('[data-method-target]').forEach(b=>b.addEventListener('click',()=>{const m=REFERENCE_METHODS.find(m=>m.id===b.dataset.methodTarget);openReference(m.kind==='forecast'?'ref-forecast':'ref-predict',m.id)}));
 };target.addEventListener('change',update);pattern.addEventListener('change',update);update();
}
// Pure numerical helpers are also exercised independently by the verification script.
function refForecasts(train,horizon){
 const n=train.length,mean=a=>a.reduce((s,x)=>s+x,0)/a.length;let level=train[0];for(let i=1;i<n;i++)level=.3*train[i]+.7*level;
 const features=t=>[1,t,Math.sin(2*Math.PI*t/12),Math.cos(2*Math.PI*t/12)];
 const A=Array.from({length:4},()=>Array(5).fill(0));train.forEach((y,t)=>{const x=features(t);for(let i=0;i<4;i++){for(let j=0;j<4;j++)A[i][j]+=x[i]*x[j];A[i][4]+=x[i]*y}});
 for(let c=0;c<4;c++){let best=c;for(let r=c+1;r<4;r++)if(Math.abs(A[r][c])>Math.abs(A[best][c]))best=r;[A[c],A[best]]=[A[best],A[c]];const pivot=A[c][c];if(Math.abs(pivot)<1e-10)throw Error('Insufficient independent observations');for(let j=c;j<5;j++)A[c][j]/=pivot;for(let r=0;r<4;r++)if(r!==c){const f=A[r][c];for(let j=c;j<5;j++)A[r][j]-=f*A[c][j]}}
 const beta=A.map(r=>r[4]);return {naive:Array(horizon).fill(train[n-1]),seasonal:Array.from({length:horizon},(_,j)=>train[n-12+j%12]),drift:Array.from({length:horizon},(_,j)=>train[n-1]+(j+1)*(train[n-1]-train[0])/(n-1)),ses:Array(horizon).fill(level),harmonic:Array.from({length:horizon},(_,j)=>features(n+j).reduce((s,v,k)=>s+v*beta[k],0))};
}
function refError(actual,pred){const errors=actual.map((a,i)=>a-pred[i]);return {mae:errors.reduce((s,e)=>s+Math.abs(e),0)/errors.length,rmse:Math.sqrt(errors.reduce((s,e)=>s+e*e,0)/errors.length),bias:errors.reduce((s,e)=>s+e,0)/errors.length};}
function mountForecastLab(){
 const $=id=>modalBody.querySelector('#'+id);const names={naive:'Last-value naïve',seasonal:'Seasonal naïve',drift:'Drift',ses:'Exponential smoothing',harmonic:'Trend + Fourier regression'};let exportRows=[];
 const update=()=>{
  const pattern=$('forecast-pattern').value,method=$('forecast-method').value,h=+$('forecast-horizon').value,show=$('show-actuals').checked;$('horizon-label').textContent=h+' period'+(h===1?'':'s');
  const values=Array.from({length:48},(_,t)=>{const noise=[-2,3,-1,2,0,-3,1,2,-2,1,0,-1][t%12]+Math.sin(t*2.31)*1.7;const trend=pattern==='flat'?0:t*.7;const season=pattern==='season'||pattern==='break'?13*Math.sin(2*Math.PI*t/12):0;return 70+trend+season+noise+(pattern==='break'&&t>=36?25:0)});
  const train=values.slice(0,36),actual=values.slice(36,36+h),predictions=refForecasts(train,h),pred=predictions[method];
  const yMin=Math.floor((Math.min(...train,...Object.values(predictions).flat(),...actual)-8)/10)*10,yMax=Math.ceil((Math.max(...train,...Object.values(predictions).flat(),...actual)+8)/10)*10;
  const X=t=>50+t*640/47,Y=v=>255-(v-yMin)*205/(yMax-yMin),path=(arr,start=0)=>arr.map((v,i)=>(i?'L':'M')+X(start+i).toFixed(2)+','+Y(v).toFixed(2)).join(' ');
  const grid=Array.from({length:5},(_,i)=>{const v=yMin+(yMax-yMin)*i/4;return '<path d="M50 '+Y(v)+'H696" stroke="#e7edf2"/><text x="40" y="'+(Y(v)+4)+'" text-anchor="end">'+v.toFixed(0)+'</text>'}).join('');
  $('forecast-chart').innerHTML=`<svg viewBox="-29 0 749 314" role="img" aria-label="Synthetic ${pattern} scenario. Training periods 1 to 36, ${h} forecast periods, selected method ${names[method]}."><g font-family="system-ui" font-size="11" fill="#718596"><rect x="${X(35.5)}" y="36" width="${696-X(35.5)}" height="219" fill="#f1f6fb"/><text x="30" y="23">OBSERVED HISTORY</text><text x="${X(35.5)+14}" y="23">FORECAST</text>${grid}<path d="M${X(35.5)} 36V255" stroke="#8eaabd" stroke-dasharray="4 4"/><path d="${path(train)}" fill="none" stroke="#496b80" stroke-width="2"/><path class="forecast-line" d="${path([train[35],...pred],35)}" fill="none" stroke="#397f99" stroke-width="2.5"/>${show?'<path d="'+path([train[35],...actual],35)+'" fill="none" stroke="#b18762" stroke-width="1.8" stroke-dasharray="5 4"/>':''}${[0,11,23,35,47].map(t=>'<text x="'+X(t)+'" y="277" text-anchor="middle">'+(t+1)+'</text>').join('')}<text x="365" y="303" text-anchor="middle">Period · schematic units of demand</text></g></svg><div class="chart-legend"><span><i style="background:#496b80"></i>History</span><span><i style="background:#397f99"></i>${names[method]}</span>${show?'<span><i style="background:#b18762"></i>Future actuals</span>':''}</div>`;
  const rows=Object.entries(predictions).map(([id,p])=>{const m=refError(actual,p);return [id,m]});
  $('forecast-metrics').innerHTML=show?refTable(['Method','MAE ↓','RMSE ↓','Bias (actual − forecast)'],rows.map(([id,m])=>[id===method?'<strong>'+names[id]+' · selected</strong>':names[id],m.mae.toFixed(2),m.rmse.toFixed(2),m.bias.toFixed(2)])):'<p class="ref-empty">Future actuals are hidden. Reveal them to evaluate error.</p>';
  const explain={naive:'Repeats observation 36 for every future period. It cannot project a trend or seasonal cycle.',seasonal:'Repeats observations from the matching period in the last 12-period cycle. It does not estimate growth.',drift:'Extends the slope between the first and last training observations. Endpoint noise can materially affect the slope.',ses:'Updates level as 0.3 × latest value + 0.7 × previous level. All multi-step forecasts equal the final level; no trend or seasonality is modeled.',harmonic:'Fits ordinary least squares on [1, time, sin(2πt/12), cos(2πt/12)] using periods 1–36 only. The trend and seasonal period are assumptions, not discoveries.'};
  $('forecast-explanation').innerHTML='<p><strong>How this forecast works:</strong> '+explain[method]+'</p>'+(pattern==='break'?'<p><strong>Notice the blind spot:</strong> an unannounced shift begins after the cutoff. None of these history-only methods is told the change in advance.</p>':'');
  exportRows=actual.map((v,i)=>[37+i,v,...Object.values(predictions).map(p=>p[i])]);
  $('forecast-data').innerHTML=refTable(['Period','Actual',...Object.values(names)],exportRows.map(r=>r.map((v,i)=>i?v.toFixed(3):v)))+'<p class="ref-small">Values are unrounded for calculations. Displayed values are rounded.</p>';
  // Match column order explicitly: object insertion order is naive, seasonal, drift, ses, harmonic.
 };
 ['forecast-pattern','forecast-method','forecast-horizon','show-actuals'].forEach(id=>$(id).addEventListener(id==='forecast-horizon'?'input':'change',update));
 $('replay-forecast').addEventListener('click',()=>{const path=$('forecast-chart').querySelector('.forecast-line');path.classList.remove('draw-line');void path.getBoundingClientRect();path.style.setProperty('--line-length',path.getTotalLength());path.classList.add('draw-line')});
 $('forecast-download').addEventListener('click',()=>refDownload('forecast-comparison.csv',['period,actual,naive,seasonal_naive,drift,ses_alpha_0_3,trend_fourier',...exportRows.map(r=>r.join(','))].join('\n'),'text/csv'));update();
}
const REF_LABELS=[{p:.08,y:0},{p:.16,y:0},{p:.22,y:1},{p:.31,y:0},{p:.39,y:0},{p:.46,y:1},{p:.53,y:0},{p:.61,y:1},{p:.69,y:1},{p:.77,y:0},{p:.86,y:1},{p:.94,y:1}];
function refConfusion(rows,threshold,fpCost,fnCost){let tp=0,fp=0,tn=0,fn=0;rows.forEach(r=>{if(r.p>=threshold){if(r.y)tp++;else fp++}else{if(r.y)fn++;else tn++}});return {tp,fp,tn,fn,cost:fp*fpCost+fn*fnCost,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null};}
function mountThresholdLab(){
 const $=id=>modalBody.querySelector('#'+id);const update=()=>{const threshold=+$('threshold-value').value/100,fpCost=Math.max(0,Math.min(10000,+$('fp-cost').value||0)),fnCost=Math.max(0,Math.min(10000,+$('fn-cost').value||0));const c=refConfusion(REF_LABELS,threshold,fpCost,fnCost);$('threshold-label').textContent=threshold.toFixed(2);
  const X=p=>45+630*p;
  $('threshold-chart').innerHTML=`<svg viewBox="-48 -13 768 174" role="img" aria-label="Twelve example probability scores; a vertical threshold separates unflagged and flagged cases. Filled dots are actual positives; hollow dots are actual negatives."><g font-family="system-ui" font-size="11" fill="#637e90"><rect x="${X(threshold)}" y="28" width="${675-X(threshold)}" height="96" rx="3" fill="#edf5f3"/><text x="45" y="18">SCORES BELOW THRESHOLD</text><text x="482" y="18">FLAGGED FOR ACTION</text><path d="M45 92H675" stroke="#d2e0e7"/><path d="M${X(threshold)} 26V128" stroke="#568c8b" stroke-dasharray="3 3"/>${REF_LABELS.map((r,i)=>'<circle cx="'+X(r.p)+'" cy="'+(i%2?73:52)+'" r="7" fill="'+(r.y?'#497e92':'white')+'" stroke="#497e92" stroke-width="1.5"><title>Case '+(i+1)+': score '+r.p+', actual '+r.y+'</title></circle>').join('')}${[0,.25,.5,.75,1].map(v=>'<text x="'+X(v)+'" y="113" text-anchor="middle">'+v.toFixed(2)+'</text>').join('')}<text x="360" y="149" text-anchor="middle">Filled dot = actual positive · hollow dot = actual negative</text></g></svg>`;
  $('threshold-results').innerHTML='<div class="confusion-grid"><div><small>TRUE POSITIVE</small><strong>'+c.tp+'</strong><span>Correctly flagged</span></div><div><small>FALSE POSITIVE</small><strong>'+c.fp+'</strong><span>Unnecessary action</span></div><div><small>FALSE NEGATIVE</small><strong>'+c.fn+'</strong><span>Missed positive</span></div><div><small>TRUE NEGATIVE</small><strong>'+c.tn+'</strong><span>Correctly unflagged</span></div></div><div class="metric-strip"><p><small>Precision</small><strong>'+(c.precision===null?'Unavailable':(100*c.precision).toFixed(1)+'%')+'</strong></p><p><small>Recall</small><strong>'+(100*c.recall).toFixed(1)+'%</strong></p><p><small>Illustrative error cost</small><strong>'+c.cost.toFixed(2)+'</strong></p></div><p class="ref-small">Cost = '+c.fp+' false positives × '+fpCost+' + '+c.fn+' missed positives × '+fnCost+'. Cost units are defined by you.</p>';
  $('threshold-data').innerHTML=refTable(['Case','Score','Actual','Decision'],REF_LABELS.map((r,i)=>[i+1,r.p.toFixed(2),r.y?'Positive':'Negative',r.p>=threshold?'Flag':'Do not flag']));
 };['threshold-value','fp-cost','fn-cost'].forEach(id=>$(id).addEventListener('input',update));update();
}
