function vibrantEsc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function vibrantFixes(fixes){return '<div class="v-fixes">'+fixes.map((f,i)=>'<div class="v-fix"><span class="v-number" aria-hidden="true">'+(i+1)+'</span><div><strong>'+vibrantEsc(f.name)+'</strong>'+(f.desc?'<p>'+vibrantEsc(f.desc)+'</p>':'')+'</div></div>').join('')+'</div>';}
