function approvedText(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function approvedActions(fixes){return '<div class="approved-actions">'+fixes.map((f,i)=>'<section class="approved-action" style="--accent:'+['#0F766E','#2563EB','#7C3AED'][i]+'"><div class="approved-action-title"><span class="approved-number" aria-hidden="true">'+(i+1)+'</span><h4>'+approvedText(f.name)+'</h4></div><p>'+approvedText(f.desc)+'</p></section>').join('')+'</div>';}
function approvedPanel(rows,after,outcome,note){
 const colors=after?['#0F766E','#2563EB','#7C3AED']:['#DC2626','#C2410C','#BE185D'];
 return '<section class="approved-panel '+(after?'approved-after':'approved-before')+'"><h4><span class="approved-panel-icon" aria-hidden="true">'+(after?'✓':'!')+'</span>'+(after?'Best Practice':'Common Mistake')+'</h4><ol class="approved-steps">'+rows.map((r,i)=>'<li style="--accent:'+colors[i]+'"><span class="approved-step-number" aria-hidden="true">'+(after?i+1:'×')+'</span><div><strong>'+approvedText(r.name)+'</strong><p>'+approvedText(r.desc)+'</p></div></li>').join('')+'</ol><div class="approved-outcome"><strong>'+approvedText(outcome)+'</strong><p>'+approvedText(note)+'</p></div></section>';
}
