  function animateCharts() {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    modalBody.querySelectorAll('.svg-chart').forEach(card => {
      const svg = card.querySelector('svg');
      card.classList.remove('chart-anim');
      if (!svg) return;
      let root = svg;
      if (svg.children.length === 1 && svg.firstElementChild.tagName.toLowerCase() === 'g') root = svg.firstElementChild;
      let i = 0;
      Array.prototype.forEach.call(root.children, el => {
        // an element carrying its own opacity attribute must not be animated:
        // the CSS animation would override the attribute and force it to 1
        if (el.hasAttribute('opacity') || el.hasAttribute('fill-opacity') || el.hasAttribute('stroke-opacity')) { i++; return; }
        el.classList.add('ci');
        el.style.setProperty('--i', Math.min(i++, 20));
      });
      let n = 0;
      svg.querySelectorAll('path, polyline, line').forEach(el => {
        if (n >= 22) return;
        const st = el.getAttribute('stroke');
        if (!st || st === 'none') return;
        if (el.getAttribute('stroke-dasharray') || el.style.strokeDasharray) return;
        let L = 0;
        try { L = el.getTotalLength ? el.getTotalLength() : 0; } catch (e) { return; }
        if (!L || L > 1500) return;
        n++;
        el.style.setProperty('--L', L.toFixed(1));
        el.style.setProperty('--i', Math.min(n + 1, 20));
        el.classList.add('cd');
      });
      void card.offsetWidth;
      card.classList.add('chart-anim');
    });
  }

function fitPopupTables(){
 modalBody.querySelectorAll('table').forEach(table=>{
  if(table.dataset.popupFit)return;table.dataset.popupFit='true';
  const cols=Math.max(0,...[...table.rows].map(row=>[...row.cells].reduce((sum,cell)=>sum+(cell.colSpan||1),0)));
  if(cols>8){table.dataset.popupColumns='wide';table.style.setProperty('--popup-table-width',Math.min(1200,cols*85)+'px');}
  let wrapper=table.closest('.rd-scroll,.popup-table-scroll');
  if(!wrapper){wrapper=document.createElement('div');wrapper.className='popup-table-scroll';table.before(wrapper);wrapper.append(table);}
  wrapper.tabIndex=0;wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label','Scrollable table: '+(table.caption?.textContent||modalTitle.textContent));
 });
}
const popupTableObserver=new MutationObserver(records=>{
 if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('table')||n.querySelector?.('table')))))fitPopupTables();
});
popupTableObserver.observe(modalBody,{childList:true,subtree:true});


