  (function buildSearch() {
    const bar = document.querySelector('.tab-bar');
    const wrap = document.createElement('div');
    wrap.className = 'search-wrap';
    wrap.innerHTML = '<span class="sw-icon">🔎</span><input id="tileSearch" type="search" placeholder="Search every topic, formula or term (e.g. p-value, XLOOKUP, bias)…" aria-label="Search topics"><span class="sw-count" id="swCount"></span><button type="button" class="sw-clear" id="swClear" aria-label="Clear search">✕</button>';
    bar.insertAdjacentElement('beforebegin', wrap);
    const input = wrap.querySelector('#tileSearch');
    const count = wrap.querySelector('#swCount');
    const clear = wrap.querySelector('#swClear');
    let results = null;
    function run() {
      const q = input.value.trim().toLowerCase();
      clear.style.display = q ? 'inline-flex' : 'none';
      document.querySelectorAll('.search-results').forEach(n => n.remove());
      if (!q) {
        document.body.classList.remove('searching');
        count.textContent = '';
        return;
      }
      document.body.classList.add('searching');
      const words = q.split(/\s+/).filter(Boolean);
      const hits = allTiles.filter(t => {
        const k = t.dataset.modal; const hay = searchIndex[k] || '';
        return words.every(w => hay.includes(w));
      });
      count.textContent = hits.length + ' match' + (hits.length === 1 ? '' : 'es');
      const box = document.createElement('div');
      box.className = 'search-results card';
      if (!hits.length) {
        box.innerHTML = '<div class="placeholder"><strong>No topics match "' + esc(q) + '"</strong>Try a shorter word, or search by function name such as SUMIFS, CI or bias.</div>';
      } else {
        let h = '<div class="sr-grid">';
        hits.forEach(t => {
          const k = t.dataset.modal; const d = CONTENT[k];
          h += '<button class="sr-item" data-open="' + k + '"><span class="sr-icon">' + (d.icon || '📘') + '</span><span><span class="sr-title">' + esc(d.title) + '</span><span class="sr-tag">' + esc(d.tag || '') + '</span></span></button>';
        });
        h += '</div>';
        box.innerHTML = h;
        box.querySelectorAll('[data-open]').forEach(b => b.addEventListener('click', () => openModal(b.dataset.open)));
      }
      document.querySelector('.tab-bar').insertAdjacentElement('afterend', box);
    }
    input.addEventListener('input', run);
    clear.addEventListener('click', () => { input.value = ''; run(); input.focus(); });
    document.addEventListener('keydown', e => {
      if (e.key === '/' && document.activeElement !== input && !overlay.classList.contains('open')) { e.preventDefault(); input.focus(); }
    });
  })();

