function fitLearningGraphics(root){
 root.querySelectorAll('.svg-chart').forEach(box=>{const svg=box.querySelector('svg');if(!svg||svg.dataset.fitFixed)return;
  svg.dataset.fitFixed='true';svg.setAttribute('preserveAspectRatio','xMidYMid meet');svg.classList.add('learn-flow-svg');
  const v=(svg.getAttribute('viewBox')||'').split(/[ ,]+/).map(Number);if(v.length!==4||v.some(x=>!Number.isFinite(x)))return;
  let bounds={x:v[0],y:v[1],right:v[0]+v[2],bottom:v[1]+v[3]};
  try{const b=svg.getBBox();if(b.width>0&&b.height>0){bounds.x=Math.min(bounds.x,b.x);bounds.y=Math.min(bounds.y,b.y);bounds.right=Math.max(bounds.right,b.x+b.width);bounds.bottom=Math.max(bounds.bottom,b.y+b.height);}}catch{}
  svg.querySelectorAll('rect,circle,text').forEach(el=>{const tag=el.tagName.toLowerCase();let x=+(el.getAttribute('x')||el.getAttribute('cx')||0),y=+(el.getAttribute('y')||el.getAttribute('cy')||0),right=x,bottom=y;
   if(tag==='rect'){right=x+(+el.getAttribute('width')||0);bottom=y+(+el.getAttribute('height')||0);}else if(tag==='circle'){const r=+el.getAttribute('r')||0;x-=r;y-=r;right=x+2*r;bottom=y+2*r;}else{const size=+el.getAttribute('font-size')||+(el.closest('[font-size]')?.getAttribute('font-size'))||10,width=el.textContent.length*size*.56,anchor=el.getAttribute('text-anchor')||el.closest('[text-anchor]')?.getAttribute('text-anchor');x-=anchor==='middle'?width/2:anchor==='end'?width:0;right=x+width;y-=size;bottom=y+size*1.35;}
   bounds.x=Math.min(bounds.x,x);bounds.y=Math.min(bounds.y,y);bounds.right=Math.max(bounds.right,right);bounds.bottom=Math.max(bounds.bottom,bottom);
  });svg.setAttribute('viewBox',[bounds.x-8,bounds.y-8,bounds.right-bounds.x+16,bounds.bottom-bounds.y+16].join(' '));
 });
}
