function showVisualGlossary(){
 const dlg=document.createElement('dialog');dlg.className='learn-glossary-dialog';dlg.setAttribute('aria-label','Visual glossary');dlg.innerHTML='<header><div><h2>Quick visual glossary</h2><p>Start with a picture, then a plain-English meaning.</p></div><button type="button" class="approved-button" data-glossary-close>Close ×</button></header><label class="glossary-search-label">Find a term<input type="search" placeholder="Try CRISP-DM, landscape, EDA, API…" aria-label="Find a glossary term"></label><div class="visual-glossary-grid"></div>';
 const render=()=>{const q=dlg.querySelector('input').value.toLowerCase();dlg.querySelector('.visual-glossary-grid').innerHTML=Object.entries(QUICK_LEARN_TERMS).filter(([,t])=>(t.label+' '+t.definition).toLowerCase().includes(q)).map(([key,t])=>'<article><h3>'+approvedText(t.label)+'</h3>'+quickMiniGraphic(t)+'<p>'+approvedText(t.definition)+'</p><small>'+approvedText(t.example)+'</small>'+(t.lesson&&CONTENT[t.lesson]?'<button type="button" class="approved-button" data-glossary-lesson="'+t.lesson+'">Open lesson →</button>':'')+'</article>').join('')||'<p>No matching term. Try a shorter word.</p>';};
 document.body.append(dlg);render();dlg.showModal();dlg.querySelector('input').addEventListener('input',render);dlg.querySelector('[data-glossary-close]').addEventListener('click',()=>dlg.close());dlg.addEventListener('close',()=>dlg.remove());dlg.addEventListener('keydown',e=>e.stopPropagation());dlg.addEventListener('click',e=>{const b=e.target.closest('[data-glossary-lesson]');if(b){const key=b.dataset.glossaryLesson;dlg.close();location.hash='#'+(modOfKey(key)||'12')+'/'+key;}});dlg.querySelector('input').focus();
}
function showHubFeedback(kind='Suggestion'){
 const dlg=document.createElement('dialog');dlg.className='hub-feedback-dialog';dlg.setAttribute('aria-label','Share feedback or appreciation');const current=CONTENT[overlay.dataset.key]?.title||(document.body.dataset.view==='module'?modById(currentModId())?.name:'Course index')||'Course index';
 dlg.innerHTML='<header><div><h2>Help this hub grow</h2><p>Suggestions, corrections and a simple thank-you are all welcome.</p></div><button type="button" class="approved-button" data-feedback-close>Close ×</button></header><label>What would you like to share?<select id="feedbackKind"><option>Suggestion</option><option>Correction</option><option>Appreciation</option><option>New topic request</option></select></label><label>Related lesson<input id="feedbackLesson" type="text" maxlength="150"></label><label>Your message<textarea id="feedbackMessage" rows="5" maxlength="1500" placeholder="What helped? What could be clearer? A concrete example is useful."></textarea></label><div class="feedback-actions"><a class="approved-button" id="feedbackEmail">Open email draft</a><button type="button" class="approved-button" id="feedbackCopy">Copy message</button></div><p class="feedback-delivery-note">This opens your email app with a draft to sawatdee@me.com. Review and send it there. Opening a draft does not send feedback automatically.</p><p id="feedbackStatus" role="status"></p>';
 document.body.append(dlg);dlg.querySelector('#feedbackKind').value=kind;dlg.querySelector('#feedbackLesson').value=current;if(kind==='Appreciation')dlg.querySelector('#feedbackMessage').value='Thank you for sharing this learning hub. I found it helpful because…';
 const message=()=>['AI Data Analytics Learning Hub',dlg.querySelector('#feedbackKind').value,'Lesson: '+dlg.querySelector('#feedbackLesson').value,'',dlg.querySelector('#feedbackMessage').value].join('\n');const refresh=()=>{dlg.querySelector('#feedbackEmail').href='mailto:sawatdee@me.com?subject='+encodeURIComponent(dlg.querySelector('#feedbackKind').value+' — AI Data Analytics Learning Hub')+'&body='+encodeURIComponent(message());};dlg.addEventListener('input',refresh);refresh();dlg.querySelector('#feedbackCopy').addEventListener('click',()=>copyText(message(),dlg.querySelector('#feedbackCopy')));dlg.querySelector('#feedbackEmail').addEventListener('click',()=>{dlg.querySelector('#feedbackStatus').textContent='Email draft requested. Send it from your email app to deliver your message.';trackHubEvent('feedback-draft-opened','Feedback draft opened');});dlg.querySelector('[data-feedback-close]').addEventListener('click',()=>dlg.close());dlg.addEventListener('close',()=>dlg.remove());dlg.addEventListener('keydown',e=>e.stopPropagation());dlg.showModal();
}
function trackHubEvent(path,title){if(HUB_ANALYTICS_ENDPOINT&&window.goatcounter?.count)window.goatcounter.count({path:'learning-hub/'+path,title,event:true});}
function setupHubAnalytics(){
 if(!HUB_ANALYTICS_ENDPOINT||!/^https:\/\/[a-z0-9-]+\.goatcounter\.com\/count\/?$/i.test(HUB_ANALYTICS_ENDPOINT))return;
 window.goatcounter={path:()=>location.pathname};const script=document.createElement('script');script.src='https://gc.zgo.at/count.js';script.async=true;script.setAttribute('data-goatcounter',HUB_ANALYTICS_ENDPOINT);document.head.append(script);
 const captureRoute=()=>{const h=parseHash();if(h.m)trackHubEvent('module-'+h.m+(h.topic?'/'+h.topic:''),h.topic?CONTENT[h.topic]?.title||h.topic:modById(h.m)?.name||h.m);};script.addEventListener('load',captureRoute);window.addEventListener('hashchange',captureRoute);
}
function mountLearningTools(){
 const toolbar=document.createElement('div');toolbar.className='learning-tools';toolbar.innerHTML='<span>Learn visually. Try a small example. Build confidence.</span><div><button type="button" class="approved-button" data-visual-glossary>Visual glossary</button><button type="button" class="approved-button" data-hub-feedback>Share feedback</button><button type="button" class="approved-button" data-hub-appreciation>Say thank you ♡</button></div>';document.querySelector('.app-header').after(toolbar);
 document.addEventListener('click',e=>{if(e.target.closest('[data-visual-glossary]'))showVisualGlossary();if(e.target.closest('[data-hub-feedback]'))showHubFeedback();if(e.target.closest('[data-hub-appreciation]'))showHubFeedback('Appreciation');});setupHubAnalytics();
}

